// The Android status bar's height, from the system's own dimension. React
// Native's StatusBar.currentHeight can still be 0 when an edge-to-edge app
// first renders.
import { PLATFORM } from "lucent:platform";
import { appContext } from "lucent:android";

/** In density-independent pixels; 0 on iOS, where scroll views inset their content themselves. */
export function statusBarHeight(): number {
  if (PLATFORM === "ios") return 0;

  const resources = appContext().getResources();
  const density = resources?.getDisplayMetrics()?.density ?? 0;
  const dimension = resources?.getIdentifier("status_bar_height", "dimen", "android") ?? 0;

  return resources && dimension > 0 && density > 0
    ? resources.getDimensionPixelSize(dimension) / density
    : 0;
}
